SELECT CASE WHEN YEAR(s.started_at) < 2024 THEN 'before_2024' WHEN YEAR(s.started_at) = 2024 THEN '2024' ELSE 'after_2024' END AS started_cohort, SUM(CASE WHEN we.event_type = 'click' THEN 1 ELSE 0 END) AS click_count, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(we.page))) AS page_values FROM web_events we LEFT JOIN sessions s ON we.session_id = s.id INNER JOIN customers c ON c.id = s.customer_id WHERE c.age != 54 GROUP BY CASE WHEN YEAR(s.started_at) < 2024 THEN 'before_2024' WHEN YEAR(s.started_at) = 2024 THEN '2024' ELSE 'after_2024' END HAVING SUM(CASE WHEN we.event_type = 'click' THEN 1 ELSE 0 END) > 54 ORDER BY page_values, click_count
